const sessoes = ($('Buscar Sessões Por Etiquetar').item.json.data) || [];
const etiquetas = (($json.data) || []).map(e => `- ${e.nome} (${e.tipo})`).join('\n') || '(nenhuma etiqueta criada ainda)';

const SYSTEM = 'És uma assistente que organiza etiquetas de clientes num CRM de uma clínica de massagens de relaxamento em Portugal (Essence Wellness).\n\n' +
  'Etiquetas já existentes no sistema:\n' + etiquetas + '\n\n' +
  'Lê as notas de uma sessão e sugere etiquetas relevantes para a cliente. Para cada coisa relevante que encontrares:\n' +
  '- Se já existir uma etiqueta que sirva, usa exatamente o nome dela (tipoSugestao: "existente")\n' +
  '- Se não existir nada parecido, sugere uma etiqueta nova (tipoSugestao: "nova"), com nome curto (2-4 palavras) e tipoEtiqueta entre saude/campanha/preferencia\n' +
  '- Antes de sugerir uma nova, confirma que não é só outra forma de dizer uma que já existe na lista\n' +
  '- Não inventes se as notas não derem informação suficiente — está tudo bem devolver uma lista vazia\n\n' +
  'Responde APENAS com um objeto JSON válido, sem markdown e sem blocos de código, com esta estrutura exata:\n' +
  '{"sugestoes": [{"etiqueta": "nome", "tipoSugestao": "existente|nova", "tipoEtiqueta": "saude|campanha|preferencia", "motivo": "frase curta"}]}';

const out = [];
for (const s of sessoes) {
  const notas = [s.resumoSessao, s.notasPosSessao].filter(Boolean).join('\n');
  const userPrompt = notas
    ? 'Notas da sessão de ' + (s.cliente && s.cliente.nome || 'cliente') + ':\n\n' + notas
    : '(sem notas de texto nesta sessão — devolve lista vazia)';
  out.push({ json: {
    sessaoId: s.id,
    clienteId: s.clienteId,
    clienteNome: (s.cliente && s.cliente.nome) || 'Cliente',
    terapeutaId: s.terapeutaId || null,
    systemPrompt: SYSTEM,
    userPrompt,
  } });
}
return out;

const prep = $('Preparar Prompts').item.json;
const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '{}';

let d;
try {
  const clean = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  d = JSON.parse(clean);
} catch (e) {
  d = { sugestoes: [] };
}
const sugestoes = Array.isArray(d.sugestoes) ? d.sugestoes : [];

return [{ json: {
  sessaoId: prep.sessaoId,
  clienteId: prep.clienteId,
  clienteNome: prep.clienteNome,
  terapeutaId: prep.terapeutaId,
  sugestoes,
} }];

